      physicalExam = "1) ATONIE UTÉRINE : utérus MOU, globuleux, flasque, remontant au-dessus de l'ombilic (absence de globe de sécurité !), exprimant de gros caillots lors du massage. 2) RÉTENTION PLACENTAIRE : placenta non délivré après 30 minutes ou manque d'un cotylédon à l'examen du délivre -> DÉLIVRANCE ARTIFICIELLE ET/OU RÉVISION UTÉRINE IMMÉDIATE ! 3) DÉCHIRURE TRAUMATIQUE : saignement rouge vif continu ALORS QUE L'UTÉRUS EST BIEN RÉTRACTÉ ET DUR (« globe de sécurité présent » !) -> EXAMEN SOUS VALVES OBLIGATOIRE ! Signes de choc tardifs (tachycardie -> hypotension -> pâleur -> marbrures).",
      associatedSigns = listOf("Tachycardie compensatrice (> 100–110 bpm -> alerte précoce avant la chute tensionnelle !!)", "Globe vésical plein (empêche l'utérus de se rétracter -> SONDAGE ÉVACUATEUR IMMÉDIAT !!)", "Hématome vulvo-vaginal / thrombus (douleur périnéale atroce post-accouchement avec choc sans grand saignement extérieur !!)"),
      clinicalSignificance = "La prise en charge chronométrée en étapes (0–30 min : révision utérine + examen sous valves + sondage vésical + massage utérin + Ocytocine IV -> si échec à 30 min : Sulprostone IVSE + Acide tranexamique + ballon de tamponnement intra-utérin ; si échec : embolisation ou chirurgie d'hémostase !) sauve la vie.",
      differentialDiagnoses = listOf("Thrombus vulvo-vaginal (hématome disséquant pelvien : peu de sang visible dehors mais douleur périnéale atroce + masse violacée + choc rapide !)", "Rupture utérine méconnue lors de l'accouchement (surtout si utérus cicatriciel -> vérifier lors de la révision utérine !)", "Inversion utérine aiguë (fond utérin retourné dans le vagin en boule rouge -> choc neurogène brutal !)"),
      complementaryExams = listOf("Bilan biologique STAT : NFS-Plaquettes, TP, TCA, FIBRINOGÈNE (cible > 2 g/L !!), Lactates, HemoCue au lit du malade toutes les 15–30 min, vérification Carte de Groupe + RAI récentes (< 72h)", "Commande immédiate de Culots Globulaires + Plasma Frais Congelé (ratio 1:1) dès hémorragie sévère >= 1000 mL"),
      gravitySigns = listOf("Pertes >= 1000–1500 mL ou instabilité hémodynamique malgré remplissage", "Chute rapide du fibrinogène < 2 g/L (CIVD de consommation !)", "Absence d'arrêt du saignement sous Sulprostone IVSE (nécessité de ballonnet de Bakri, embolisation artères utérines ou hystérectomie d'hémostase)"),
      pitfallsAndLimits = "1. L'estimation visuelle à l'œil nu sous-estime de 50% le volume sanguin perdu : le SAC DE RECUEIL GRADUÉ est obligatoire ! 2. Un utérus bien contracté et dur qui continue à saigner rouge vif impose l'EXAMEN SOUS VALVES (recherche de déchirure du col ou vaginale) et ne cèdera jamais sous massage utérin seul ! 3. Oublier de vider une vessie pleine empêche physiquement l'utérus de se contracter.",
      keyPoints = listOf("HPP >= 500 mL (sac gradué !) = Urgence absolue chronométrée (cause n°1 = Atonie utérine 70%)", "4 gestes réflexes immédiats : Sondage vésical + Révision utérine + Examen sous valves (si globe dur !) + Ocytocine IV & Massage", "Échec Ocytocine -> Sulprostone (Nalador) IVSE + Acide Tranexamique + Fibrinogène/Transfusion -> Ballon/Embolisation")
